with recent_web_events as (select * from web_events where session_id in (7, 38, 39)), agg as (select case when event_type in ('search', 'add_to_cart') then 'core' else 'other' end event_type_group, max(duration_sec) max_duration_sec from recent_web_events group by case when event_type in ('search', 'add_to_cart') then 'core' else 'other' end) select * from agg order by event_type_group limit 5;
